def board_numbers(bibs):
    # Example: board_numbers(['000', '15']) returns ['0', '15']
    labels = []
    for code in bibs:
        digits = code.lstrip("0")
        if digits == '':
            digits = '0'
        labels.append(digits)
    return labels

